// Some portions generated by Claude

// A resource shown with a prefix has a copy button that appears on hover (and keyboard focus) and copies the complete
// IRI.
// @ts-check
const { test, expect } = require('@playwright/test');
const {
	createSeededRepository,
	deleteRepository,
	repositoryPageUrl,
	serverBaseUrl,
	uniqueRepositoryId,
	waitForRoute
} = require('./workbench-test-helpers.js');

const REPOSITORY_ID = uniqueRepositoryId('workbench-copy-resource');
const BSBM_INSTANCES = 'http://www4.wiwiss.fu-berlin.de/bizer/bsbm/v01/instances/';

test.describe.configure({ mode: 'serial' });

test.beforeAll(async ({ request }) => {
	await createSeededRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

test.afterAll(async ({ request }) => {
	await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

const opacity = (locator) => locator.evaluate((element) => Number(getComputedStyle(element).opacity));

test('a prefixed IRI in the query results shows its copy button on hover and copies the whole IRI',
	async ({ page, context, browserName }) => {
		test.skip(browserName !== 'chromium', 'clipboard permissions are granted only in Chromium');
		await context.grantPermissions(['clipboard-read', 'clipboard-write']);
		await page.setViewportSize({ width: 1280, height: 900 });
		await page.goto(repositoryPageUrl(REPOSITORY_ID, 'query'), { waitUntil: 'domcontentloaded' });
		await waitForRoute(page, 'query');
		await page.locator('#query-page .CodeMirror').first().evaluate((element, query) => element.CodeMirror.setValue(query),
			'SELECT ?type WHERE { <' + BSBM_INSTANCES + 'ProductType2> <http://www.w3.org/2000/01/rdf-schema#subClassOf> ?type }');
		await page.locator('#exec').click();
		const cell = page.locator('#query-results .resource').filter({ hasText: 'bsbm-inst:ProductType1' }).first();
		await expect(cell).toBeVisible();
		const copy = cell.locator('.resource-copy');
		await page.mouse.move(0, 0);
		await expect.poll(() => opacity(copy)).toBe(0);

		await cell.hover();
		await expect.poll(() => opacity(copy)).toBe(1);
		await expect(copy).toHaveAccessibleName('Copy ' + BSBM_INSTANCES + 'ProductType1');
		await copy.click();
		await expect(copy).toHaveAttribute('aria-label', 'Copied');
		expect(await page.evaluate(() => navigator.clipboard.readText())).toBe(BSBM_INSTANCES + 'ProductType1');
	});

test('on a narrow screen a type\'s buttons stay beside its name in the record card', async ({ page }) => {
	await page.setViewportSize({ width: 375, height: 812 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'types'), { waitUntil: 'domcontentloaded' });
	const cell = page.locator('#types-results td[data-label="Type"]')
		.filter({ has: page.getByRole('link', { name: 'bsbm:Product', exact: true }) });
	await expect(cell).toBeVisible({ timeout: 15000 });
	const name = await cell.locator('a').first().boundingBox();
	for (const selector of ['.resource-copy', '.workbench-add-to-graph']) {
		const button = await cell.locator(selector).boundingBox();
		expect(button, selector).not.toBeNull();
		expect(button.x, selector + ' follows the name').toBeGreaterThanOrEqual(name.x + name.width);
		expect(Math.abs((button.y + button.height / 2) - (name.y + name.height / 2)), selector + ' on the name\'s line')
			.toBeLessThan(name.height);
	}
});

test('the copy button after an Explore group member is reached from the keyboard', async ({ page }) => {
	await page.setViewportSize({ width: 1280, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'explore') + '?resource='
		+ encodeURIComponent('<' + BSBM_INSTANCES + 'ProductType1>'), { waitUntil: 'domcontentloaded' });
	await waitForRoute(page, 'explore');
	const member = page.locator('.workbench-explore-groups li').filter({ hasText: 'bsbm-inst:ProductType2' });
	const copy = member.locator('.resource-copy');
	await member.locator('a').focus();
	await page.mouse.move(0, 0);
	await page.keyboard.press('Tab');

	await expect(copy).toBeFocused();
	await expect.poll(() => opacity(copy)).toBe(1);
	await expect(copy).toHaveAccessibleName('Copy ' + BSBM_INSTANCES + 'ProductType2');
});
